pure def settle(v: State, r: str): State = {
  ...v,
  result: if (v.result == "none") r else v.result
}

action Fire = all {
  s.timer == "armed",
  s' = {
    ...s,
    timer: "fired",
    tHas: s.inMap,
    inMap: false,
    tpc: if (s.inMap) "getTask" else "done"
  }
}

action TGetTask = all {
  s.tpc == "getTask",
  s' = if (s.taskExists) {
    ...s,
    tpc: "onTimeout",
    toRuns: s.toRuns + 1
  } else {
    ...s,
    tpc: "resolve"
  }
}

action TCallbackDone = all {
  s.tpc == "onTimeout",
  s' = {
    ...s,
    tpc: "resolve"
  }
}

action TCallbackFails = all {
  CanFail,
  s.tpc == "onTimeout",
  s' = settle({
    ...s,
    tpc: "done",
    inMap: false
  }, "rejected")
}

action TResolve = all {
  s.tpc == "resolve",
  s' = settle({
    ...s,
    tpc: "deleteTask"
  }, "timedOut")
}

action TDelete = all {
  s.tpc == "deleteTask",
  s' = {
    ...s,
    taskExists: false,
    tpc: "done"
  }
}

action Deliver(i: str): bool = all {
  s.spc.get(i) == "idle",
  s.taskExists,
  s' = {
    ...s,
    spc: s.spc.set(i, "getTask")
  }
}

action SGetTask(i: str): bool = all {
  s.spc.get(i) == "getTask",
  s' = if (not(s.taskExists)) {
    ...s,
    spc: s.spc.set(i, "deleteTask")
  } else {
    ...s,
    sHas: s.sHas.set(i, s.inMap),
    inMap: false,
    timer: if (s.inMap and s.timer == "armed") "cleared" else s.timer,
    spc: s.spc.set(i, if (s.inMap) "onSelect" else if (s.stopped) "deleteTask" else "done"),
    selRuns: if (s.inMap) s.selRuns + 1 else s.selRuns
  }
}

action SCallbackDone(i: str): bool = all {
  s.spc.get(i) == "onSelect",
  s' = settle({
    ...s,
    spc: s.spc.set(i, "deleteTask")
  }, "selected")
}

action SCallbackFails(i: str): bool = all {
  CanFail,
  s.spc.get(i) == "onSelect",
  s' = settle({
    ...s,
    spc: s.spc.set(i, "done")
  }, "rejected")
}

action SDelete(i: str): bool = all {
  s.spc.get(i) == "deleteTask",
  s' = {
    ...s,
    taskExists: false,
    spc: s.spc.set(i, "done")
  }
}

pure def cancel(v: State): State = if (v.inMap) settle({
  ...v,
  timer: if (v.timer == "armed") "cleared" else v.timer,
  inMap: false
}, "cancelled") else v

action Cancel = all {
  s.cpc == "idle",
  s' = {
    ...cancel(s),
    cpc: "deleteTask"
  }
}

action CancelDelete = all {
  s.cpc == "deleteTask",
  s' = {
    ...s,
    taskExists: false,
    cpc: "done"
  }
}

action Stop = all {
  not(s.stopped),
  s' = {
    ...cancel(s),
    stopped: true
  }
}

action SelectionStep = {
  nondet i = Selectors.oneOf()
  any {
    Deliver(i),
    SGetTask(i),
    SCallbackDone(i),
    SCallbackFails(i),
    SDelete(i)
  }
}

action step = any {
  nextStep,
  s' = s
}

val ResultAgrees = and {
  s.result == "cancelled" implies s.selRuns + s.toRuns == 0,
  s.result == "selected" implies s.toRuns == 0,
  s.result == "timedOut" implies s.selRuns == 0
}

temporal Fairness = and {
  Fire.weakFair(s),
  TGetTask.weakFair(s),
  any {
    TCallbackDone,
    TCallbackFails
  }.weakFair(s),
  TResolve.weakFair(s),
  TDelete.weakFair(s),
  Selectors.forall(i => and {
    SGetTask(i).weakFair(s),
    any {
      SCallbackDone(i),
      SCallbackFails(i)
    }.weakFair(s),
    SDelete(i).weakFair(s)
  })
}

action init = s' = {
  stopped: false, retired: false, replacement: false,
  phase: "idle", task: false, result: "none"
}

action Admit = all {
  not(s.stopped), s.phase == "idle",
  s' = { ...s, phase: "creating" }
}

action BeginList = all {
  not(s.stopped), s.phase == "idle",
  s' = { ...s, phase: "listing" }
}

action ListSettles = all {
  s.phase == "listing",
  s' = { ...s, phase: "done" }
}

action WriteDone = all {
  s.phase == "creating",
  s' = { ...s, phase: "publish", task: true }
}

action WriteFailed = all {
  s.phase == "creating",
  s' = { ...s, phase: "done", result: "rejected" }
}

action Publish = all {
  s.phase == "publish",
  s' = { ...s, phase: if (s.stopped) "cleanup" else "pending" }
}

action Cleanup = all {
  s.phase == "cleanup",
  s' = { ...s, phase: "done", task: false, result: "rejected" }
}

action BeginSelection = all {
  not(s.stopped), s.phase == "pending",
  s' = { ...s, phase: "selectionRead" }
}

action BeginTimeout = all {
  not(s.stopped), s.phase == "pending",
  s' = { ...s, phase: "timeoutRead" }
}

action ReadSelection = all {
  s.phase == "selectionRead",
  s' = { ...s, phase: if (s.stopped) "selectDelete" else "selectCallback" }
}

action SelectionReadFails = all {
  s.phase == "selectionRead",
  s' = { ...s, phase: if (s.stopped) "done" else "pending" }
}

action ReadTimeout = all {
  s.phase == "timeoutRead",
  s' = { ...s, phase: "timeoutCallback" }
}

action CallbackDone = all {
  Set("selectCallback", "timeoutCallback").contains(s.phase),
  s' = { ...s,
    phase: if (s.phase == "selectCallback") "selectDelete" else "timeoutDelete",
    result: if (s.phase == "selectCallback") "selected" else "timedOut"
  }
}

action CallbackFailed = all {
  Set("timeoutRead", "selectCallback", "timeoutCallback").contains(s.phase),
  s' = { ...s, phase: "done", result: if (s.result == "none") "rejected" else s.result }
}

action DeleteDone = all {
  Set("selectDelete", "timeoutDelete").contains(s.phase),
  s' = { ...s, phase: "done", task: false }
}

action DeleteFailed = all {
  Set("selectDelete", "timeoutDelete", "cleanup").contains(s.phase),
  s' = { ...s, phase: "done", result: if (s.result == "none") "rejected" else s.result }
}

action Cancel = all {
  s.phase == "pending",
  s' = { ...s, phase: "selectDelete", result: "cancelled" }
}

action Stop = all {
  not(s.stopped),
  s' = { ...s, stopped: true,
    phase: if (s.phase == "pending") "done" else s.phase,
    result: if (inMap) "cancelled" else s.result
  }
}

action Retire = all {
  s.stopped, not(s.retired), not(busy),
  s' = { ...s, retired: true }
}

action Replace = all {
  s.retired, not(s.replacement),
  s' = { ...s, replacement: true }
}

action step = any {
  Admit, BeginList, ListSettles, WriteDone, WriteFailed, Publish, Cleanup,
  BeginSelection, BeginTimeout, ReadSelection, SelectionReadFails, ReadTimeout,
  CallbackDone, CallbackFailed, DeleteDone, DeleteFailed, Cancel, Stop,
  Retire, Replace, s' = s
}

action Select = all {
  s.worker, s.phase == "live",
  s' = { ...s, phase: if (NeedsCallbacks) "selectEffect" else "selectDelete",
    effect: if (NeedsCallbacks) "running" else "idle" }
}

action Timeout = all {
  s.phase == "live",
  s' = { ...s, phase: if (NeedsCallbacks) "timeoutEffect" else "timeoutDelete",
    effect: if (NeedsCallbacks) "running" else "idle" }
}

action EffectDone = all {
  Set("selectEffect", "timeoutEffect").contains(s.phase),
  s' = { ...s, effect: "success",
    phase: if (s.phase == "selectEffect") "selectDelete" else "timeoutDelete" }
}

action EffectFailed = all {
  Set("selectEffect", "timeoutEffect").contains(s.phase),
  s' = { ...s, phase: "orphan", effect: "failure" }
}

action DeleteDone = all {
  Set("selectDelete", "timeoutDelete").contains(s.phase),
  s' = { ...s, phase: if (s.phase == "selectDelete") "selected" else "deleted" }
}

action DeleteFailed = all {
  Set("selectDelete", "timeoutDelete").contains(s.phase),
  s' = { ...s, phase: "orphan" }
}

action Restart = all {
  not(s.restarted), Set("live", "orphan").contains(s.phase),
  s' = { ...s, phase: "orphan", restarted: true, worker: false }
}

action RegisterSameName = all {
  s.restarted, not(s.worker),
  s' = { ...s, worker: true }
}

action SelectPersistedFree = all {
  not(NeedsCallbacks), s.worker, s.phase == "orphan",
  s' = { ...s, phase: "selectDelete" }
}

action RejectUnavailable = all {
  NeedsCallbacks, s.worker, s.phase == "orphan", s' = s
}

action Cancel = all {
  Set("live", "orphan").contains(s.phase),
  s' = { ...s, phase: "deleted" }
}

action step = any {
  Select, Timeout, EffectDone, EffectFailed, DeleteDone, DeleteFailed,
  Restart, RegisterSameName, SelectPersistedFree, RejectUnavailable, Cancel, s' = s
}

temporal CompletionFairness = and {
  Timeout.weakFair(s), any { EffectDone, EffectFailed }.weakFair(s),
  any { DeleteDone, DeleteFailed }.weakFair(s)
}

action ProbeStart(p: str): bool = all {
  s.ppc == "idle", s.probes < MaxProbes,
  s' = {...s, ppc: "called", pprov: p, probes: s.probes + 1}
}

action ProbeResize = {
  val p = s.pprov
  val expected = if (s.pinSpace != None) s.pinSpace else space(p)
  val refused = expected != None and
    (space(p) != expected or (s.pinDim != 0 and dim(p) != s.pinDim))
  val guard = space(p) != None and s.pinProv != None and s.pinSpace != space(p)
  all {s.ppc == "called", s' =
    if (refused or guard or (s.aspace != None and dim(p) != s.col))
      {...s, ppc: "idle", pprov: None}
    else {...s, col: dim(p), ppc: "resized"}
  }
}

action ProbeSpace = {
  val target = space(s.pprov)
  all {s.ppc == "resized", s' =
    if (target != None and s.aspace != None and s.aspace != target)
      {...s, ppc: "idle", pprov: None}
    else {...s, aspace: if (target != None) target else s.aspace, ppc: "spaced"}
  }
}

action ProbePin = all {
  s.ppc == "spaced",
  s' = {...s, pinProv: s.pprov, pinSpace: space(s.pprov),
    pinDim: dim(s.pprov), ppc: "pinned"}
}

action ProbeClear = all {
  s.ppc == "pinned",
  any {
    s' = {...s, stored: s.stored.filter(v => v.space != s.aspace or v.dim == s.col),
      clearFailed: false, ppc: "idle", pprov: None},
    s' = {...s, clearFailed: true, ppc: "idle", pprov: None}
  }
}

action EmbedCall(e: str, p: str): bool = all {
  s.epc.get(e) == "idle", s.pinProv != None implies p == s.pinProv,
  s' = {...s, epc: s.epc.set(e, "called"), eprov: s.eprov.set(e, p)}
}

action EmbedValidate(e: str): bool = {
  val named = space(s.eprov.get(e))
  val expected = if (s.pinSpace != None) s.pinSpace else named
  all {
    s.epc.get(e) == "called",
    named != None and s.pinSpace == None implies s.ppc == "idle",
    s' = {...s, epc: s.epc.set(e,
      if (expected == None) "valid"
      else if (s.pinSpace == None) "done"
      else if (named == expected and dim(s.eprov.get(e)) == s.pinDim) "valid"
      else "done")}
  }
}
// Storage captures the vector's provenance and selected column before awaits.

action EmbedAdmit(e: str): bool = all {
  s.epc.get(e) == "valid",
  s' = if (space(s.eprov.get(e)) != s.aspace)
    {...s, epc: s.epc.set(e, "done"), dropped: s.dropped + 1}
  else {...s, epc: s.epc.set(e, "admitted"),
    writeSpace: s.writeSpace.set(e, space(s.eprov.get(e))),
    writeDim: s.writeDim.set(e, s.col)}
}
// Actual writes recheck the capture after every database await and retain its label.

action EmbedWrite(e: str): bool = {
  val v = {space: s.writeSpace.get(e), dim: dim(s.eprov.get(e)), from: space(s.eprov.get(e))}
  val current = s.writeSpace.get(e) == s.aspace and s.writeDim.get(e) == s.col
  all {s.epc.get(e) == "admitted", s' =
    if (current and v.dim == s.col)
      {...s, stored: s.stored.union(Set(v)), epc: s.epc.set(e, "done")}
    else {...s, dropped: s.dropped + 1, epc: s.epc.set(e, "done")}
  }
}

action DirectUnmarkedWrite(e: str): bool = all {
  s.epc.get(e) == "idle",
  s' = if (s.aspace == None)
    {...s, epc: s.epc.set(e, "done"), stored: s.stored.union(Set({space: None, dim: s.col, from: None}))}
  else {...s, epc: s.epc.set(e, "done"), dropped: s.dropped + 1}
}

action nextStep = {
  nondet p = Providers.oneOf()
  nondet e = Embedders.oneOf()
  any {ProbeStart(p), ProbeResize, ProbeSpace, ProbePin, ProbeClear,
    EmbedCall(e, p), EmbedValidate(e), EmbedAdmit(e), EmbedWrite(e),
    DirectUnmarkedWrite(e), all {Finished, s' = s}}
}

action init = s' = {
  items: Items.mapBy(_ => {
    phase: "queued", source: 0, singles: 0, receipt: "none",
    sourceAtReceipt: -1, singlesAtReceipt: -1,
    logFailed: false, notification: "none"
  }),
  batchStarted: false
}

action edit(id: int): bool = all {
  entry(id).source == 0,
  update(id, { ...entry(id), source: 1 })
}

action startBatch = all {
  Batch, not(s.batchStarted),
  s' = { batchStarted: true,
    items: Items.mapBy(id => { ...entry(id), phase: "inference" }) }
}

action settleBatch(success: bool): bool = all {
  Batch, s.batchStarted,
  Items.forall(id => entry(id).phase == "inference" and entry(id).singles == 0),
  s' = { ...s,
    items: Items.mapBy(id => {
      ...entry(id), phase: if (success) "writing" else "retry"
    }) }
}

def canSettleWrite(id: int): bool =
  not(Batch) or entry(id).singles > 0 or
    Items.filter(other => other < id).forall(primarySettled)

action startSingle(id: int): bool = all {
  (not(Batch) and entry(id).phase == "queued") or
    (entry(id).phase == "retry" and (not(Batch) or Items.forall(primarySettled))),
  update(id, { ...entry(id), phase: "inference", singles: entry(id).singles + 1 })
}

action settleSingle(id: int, success: bool): bool = all {
  entry(id).phase == "inference", entry(id).singles > 0,
  if (success) update(id, { ...entry(id), phase: "writing" })
  else failAttempt(id)
}

action settleWrite(id: int, acknowledged: bool): bool = all {
  entry(id).phase == "writing", canSettleWrite(id),
  if (acknowledged) update(id, { ...entry(id),
    phase: "logging",
    receipt: if (entry(id).source == 0) "stored" else "stale",
    sourceAtReceipt: entry(id).source, singlesAtReceipt: entry(id).singles
  }) else failAttempt(id)
}

action settleLog(id: int, failed: bool): bool = all {
  entry(id).phase == "logging",
  update(id, { ...entry(id), logFailed: failed,
    phase: if (entry(id).receipt == "stored") "notifying" else "done"
  })
}

action settleNotification(id: int, failed: bool): bool = all {
  entry(id).phase == "notifying",
  update(id, { ...entry(id), phase: "done",
    notification: if (failed) "rejected" else "sent"
  })
}

action advance(id: int): bool = any {
  startSingle(id),
  { nondet outcome = Bool.oneOf(); any {
    settleSingle(id, outcome), settleWrite(id, outcome),
    settleLog(id, outcome), settleNotification(id, outcome)
  } }
}

action advanceBatch = any {
  startBatch, { nondet success = Bool.oneOf(); settleBatch(success) }
}

action step = any {
  advanceBatch, { nondet id = Items.oneOf(); any { edit(id), advance(id) } },
  s' = s
}

val TypeOK = Items.forall(id => all {
  entry(id).phase.in(Set(
    "queued", "inference", "writing", "logging", "notifying", "retry", "done", "exhausted"
  )),
  entry(id).source.in(Set(0, 1)), entry(id).singles.in(0.to(2)),
  entry(id).receipt.in(Set("none", "stored", "stale")),
  entry(id).notification.in(Set("none", "sent", "rejected"))
})

val ExactSourceReceipt = Items.forall(id => all {
  (entry(id).receipt == "stored") == (entry(id).sourceAtReceipt == 0),
  (entry(id).receipt == "stale") == (entry(id).sourceAtReceipt == 1)
})

val ReceiptClosesRetry = Items.forall(id => (entry(id).receipt != "none").implies(all {
  entry(id).phase.in(Set("logging", "notifying", "done")),
  entry(id).singles == entry(id).singlesAtReceipt
}))

temporal Fairness = all {
  advanceBatch.weakFair(s), Items.forall(id => advance(id).weakFair(s))
}

action init = s' = {
  rows: if (Prefilled)[Set(Seed)] else[],
  pc: Writers.mapBy(w => "idle"),
  seen: Writers.mapBy(w => Set()),
  owner: Seed
}

action Check(w: str): bool = all {
  s.pc.get(w) == "idle",
  Serialised implies s.owner == Seed,
  s' = if (s.rows.length() == 0) {
    ...s,
    owner: if (Serialised) w else s.owner,
    pc: s.pc.set(w, "miss")
  } else {
    ...s,
    owner: if (Serialised) w else s.owner,
    pc: s.pc.set(w, "hit"),
    seen: s.seen.set(w, s.rows.nth(0))
  }
}

action Update(w: str): bool = all {
  s.pc.get(w) == "hit",
  s' = {
    ...s,
    rows: s.rows.replaceAt(0, s.seen.get(w).union(Set(w))),
    pc: s.pc.set(w, "done"),
    owner: if (Serialised) Seed else s.owner
  }
}

action Insert(w: str): bool = all {
  s.pc.get(w) == "miss",
  s' = {
    ...s,
    rows: s.rows.append(Set(w)),
    pc: s.pc.set(w, "done"),
    owner: if (Serialised) Seed else s.owner
  }
}

action WriterStep(w: str): bool = any {
  Check(w),
  Update(w),
  Insert(w)
}

action nextStep = {
  nondet w = Writers.oneOf()
  any {
    WriterStep(w),
    all {
      Finished,
      s' = s
    }
  }
}

action step = any {
  nextStep,
  s' = s
}

val TypeOK = and {
  s.rows.indices().forall(i => s.rows.nth(i).subseteq(Writers.union(Set(Seed)))),
  s.pc.keys() == Writers,
  Writers.forall(w => Set("idle", "hit", "miss", "done").contains(s.pc.get(w)) and s.seen.get(w).subseteq(Writers.union(Set(Seed)))),
  Writers.union(Set(Seed)).contains(s.owner)
}

action init = all {
  Mismatched.subseteq(Clients), Expiry > 0, Expiry <= MaxTime, Ttl > 0,
  s' = {exists: true, cstate: "pending", owner: noClaim, digest: None,
    lease: 0, committedAt: 0, completedAt: 0, auth: "active", now: 0,
    pc: Clients.mapBy(c => "idle"), attempts: Clients.mapBy(c => 0),
    mine: Clients.mapBy(c => noClaim), last: Clients.mapBy(c => "none"),
    effects: 0, reached: "open", late: false}
}

pure def taken(v: State, c: str, outcome: str): State = {
  val id = {client: c, attempts: v.attempts.get(c)}
  {...v, cstate: "claimed", owner: id, digest: response(c), lease: v.now + Ttl,
    pc: v.pc.set(c, "claimed"), mine: v.mine.set(c, id), last: v.last.set(c, outcome)}
}

action Claim(c: str): bool = {
  val same = s.digest == response(c)
  val v = {...s, attempts: s.attempts.set(c, s.attempts.get(c) + 1)}
  all {s.pc.get(c) == "idle", s.attempts.get(c) < MaxRuns, s' =
    if (not(s.exists)) returned(v, c, "error")
    else if (Set("pending", "claimed").contains(s.cstate) and (s.auth != "active" or s.now >= Expiry)) returned(v, c, "error")
    else if (s.cstate == "completed") returned(v, c, if (same) "replay" else "error")
    else if (s.cstate == "committed") returned(v, c, if (same) "in_progress" else "error")
    else if (s.cstate == "claimed") (
      if (not(same)) returned(v, c, "error")
      else if (s.lease > s.now) returned(v, c, "in_progress")
      else taken(v, c, "resumed"))
    else taken(v, c, "acquired")
  }
}

action Commit(c: str): bool = all {
  s.pc.get(c) == "claimed",
  s' = if (s.exists and s.cstate == "claimed" and s.owner == s.mine.get(c) and s.auth == "active" and CommitInTime)
    {...s, cstate: "committed", committedAt: s.now, pc: s.pc.set(c, "committed"),
      reached: "committed", late: s.late or s.now >= s.lease or s.now >= Expiry}
    else returned(s, c, "error")
}

action Execute(c: str): bool = all {
  s.pc.get(c) == "committed",
  s' = {...s, effects: s.effects + 1, pc: s.pc.set(c, "executed")}
}

action Complete(c: str): bool = all {
  s.pc.get(c) == "executed",
  s' = if (not(s.exists)) returned(s, c, "lost")
    else if (s.cstate == "completed" and s.digest == response(c)) returned(s, c, "completed")
    else if (s.cstate == "committed" and s.owner == s.mine.get(c))
      {...s, cstate: "completed", completedAt: s.now, reached: "completed",
        pc: s.pc.set(c, "idle"), last: s.last.set(c, "completed")}
    else returned(s, c, "error")
}

action Crash(c: str): bool = all {
  Set("claimed", "committed", "executed").contains(s.pc.get(c)), s' = returned(s, c, "crashed")
}

action Reconcile = all {
  s.exists, s.cstate == "committed", s.committedAt <= s.now, s.effects == 1,
  s' = {...s, cstate: "completed", completedAt: s.now, reached: "completed"}
}

action Revoke = all {
  s.exists, s.auth == "active", s.cstate != "committed", s' = {...s, auth: "revoked"}
}

action nextStep = {
  nondet c = Clients.oneOf()
  any {Claim(c), Commit(c), Execute(c), Complete(c), Crash(c), Reconcile, Revoke,
    DeleteExpired, Tick, all {Finished, s' = s}}
}

pure def cancelPrepared(state: State): str -> str = {
  val operation = firstUnresolved(state)
  if (operation != "none" and state.op.get(operation) == "prepared")
    state.op.set(operation, "cancelled")
  else state.op
}

pure val initialState = {
  status: "active", auth: "active", obs: "none",
  op: Ops.mapBy(operation => "none"), scopeB: false, extended: false
}

pure def observe(state: State, origin: str, resume: bool): Set[State] = {
  val operation = firstUnresolved(state)
  if (and {
    not(ended(state)), state.auth == "active",
    resume implies state.status == "paused",
    operation != "none" implies state.op.get(operation) == "prepared",
    origin == "B" implies state.scopeB
  }) Set({...state, op: cancelPrepared(state), obs: origin,
    status: if (resume) "active" else state.status})
  else Set()
}

pure def extend(state: State): Set[State] = {
  val operation = firstUnresolved(state)
  if (and {
    not(ended(state)), state.auth == "active", not(state.scopeB),
    operation != "none" implies state.op.get(operation) == "prepared"
  }) Set({...state, op: cancelPrepared(state), obs: "none", scopeB: true, extended: true})
  else Set()
}

pure def retract(state: State): Set[State] = {
  val operation = firstUnresolved(state)
  val dispatched = operation != "none" and state.op.get(operation) == "dispatched"
  if (state.scopeB) Set({...state,
    op: if (dispatched) state.op.set(operation, "unknown") else cancelPrepared(state),
    status: if (dispatched) "paused" else state.status,
    obs: "none", scopeB: false})
  else Set()
}

pure def interrupt(state: State, kind: str): Set[State] = {
  val operation = firstUnresolved(state)
  if (Set("pause", "cancel").contains(kind) implies not(ended(state))) Set({...state,
    op: if (operation != "none" and state.op.get(operation) == "dispatched")
      state.op.set(operation, "unknown") else cancelPrepared(state),
    auth: if (kind == "revoke") "revoked" else state.auth,
    status: if (ended(state)) state.status
      else if (kind == "cancel") "cancelled" else "paused"})
  else Set()
}

pure def prepare(state: State, operation: str): Set[State] =
  if (and {
    state.status == "active", state.auth == "active", state.obs != "none",
    firstUnresolved(state) == "none", state.op.get(operation) == "none"
  }) Set({...state, op: state.op.set(operation, "prepared")})
  else Set()

pure def dispatch(state: State, operation: str): Set[State] =
  if (and {
    not(ended(state)), firstUnresolved(state) == operation,
    state.op.get(operation) == "prepared"
  }) Set({...state, op: state.op.set(operation, "dispatched"), status: "waiting"})
  else Set()

pure def result(state: State, operation: str, outcome: str): Set[State] =
  if (not(ended(state)) and state.op.get(operation) == "dispatched") Set({...state,
    op: state.op.set(operation, outcome),
    status: if (state.status == "waiting")
      (if (outcome == "unknown") "blocked" else "active") else state.status})
  else Set()

pure def reconcile(state: State, operation: str, outcome: str): Set[State] =
  if (state.op.get(operation) == "unknown") Set({...state,
    op: state.op.set(operation, outcome),
    obs: if (outcome == "unknown") state.obs else "none",
    status: if (outcome != "unknown" and state.status == "blocked") "paused" else state.status})
  else Set()

pure def complete(state: State): Set[State] =
  if (not(ended(state)) and firstUnresolved(state) == "none")
    Set({...state, status: "completed"}) else Set()

action nextStep = {
  nondet nextState = successors(s).oneOf()
  s' = nextState
}

val TypeOK = and {
  Statuses.contains(s.status), Set("active", "revoked").contains(s.auth),
  Origins.union(Set("none")).contains(s.obs), s.op.keys() == Ops,
  Ops.forall(operation => OpStates.contains(s.op.get(operation)))
}

temporal OutcomesAreFinal = always((Ops.forall(operation => and {
  Set("succeeded", "failed", "cancelled").forall(outcome =>
    s.op.get(operation) == outcome implies next(s.op.get(operation)) == outcome),
  s.op.get(operation) != "none" implies next(s.op.get(operation)) != "none"
})).orKeep(s))

temporal RevocationIsFinal = always((
  s.auth == "revoked" implies next(s.auth) == "revoked"
).orKeep(s))

action graphInit = all {
  s' = initialState, seen' = Set(initialState),
  frontier' = Set(initialState), edges' = Set()
}

action graphStep = {
  val reached = frontier.fold(Set(), (found, state) => found.union(successors(state)))
  val additions = frontier.fold(Set(), (found, state) =>
    found.union(successors(state).map(target => (state, target))))
  all {
    s' = s,
    seen' = seen.union(reached),
    frontier' = reached.exclude(seen),
    edges' = edges.union(additions)
  }
}

action init = s' = {
  phase: "open", handler: Callers.mapBy(_ => "idle"), start: "idle",
  cached: false, task: false, failures: 0, retried: false,
  accepted: 0, queued: 0, processed: 0, discarded: 0,
  stopCalls: StopCallers.mapBy(_ => "idle")
}

action request(c: int): bool = all {
  s.phase == "open", s.handler.get(c) == "idle",
  s' = { ...s, handler: s.handler.set(c, "checking") }
}

action checked(c: int): bool = all {
  s.handler.get(c) == "checking",
  s' = if (s.phase == "open") {
    ...s, handler: s.handler.set(c, "returned"),
    accepted: s.accepted + 1, queued: s.queued + 1,
    cached: true, start: if (s.start == "idle") "pending" else s.start,
    retried: s.retried or (s.start == "idle" and s.failures > 0)
  } else { ...s, handler: s.handler.set(c, "rejected") }
}

action startSuccess = all {
  s.start == "pending", s' = { ...s, start: "ready", task: true }
}

action startFailure = all {
  s.start == "pending", s.failures == 0,
  s' = { ...s, start: "idle", cached: false, failures: 1 }
}

action drain = all {
  s.task, s.queued > 0, s.phase != "stopped",
  s' = { ...s, queued: s.queued - 1, processed: s.processed + 1 }
}

action stop = all {
  s.phase == "open",
  s' = { ...s, phase: "stopping", stopCalls: s.stopCalls.set(0, "waiting") }
}
// Repeated stop joins the same pending cleanup; it does not retire ownership early.

action joinStop = all {
  s.phase == "stopping", s.stopCalls.get(1) == "idle",
  s' = { ...s, stopCalls: s.stopCalls.set(1, "waiting") }
}

action stopReturns(c: int): bool = all {
  s.phase == "stopped", s.stopCalls.get(c) == "waiting",
  s' = { ...s, stopCalls: s.stopCalls.set(c, "returned") }
}

action dispose = all {
  s.phase == "stopping", s.start != "pending",
  s' = { ...s, phase: "stopped", start: "idle", cached: false, task: false,
    queued: 0, discarded: s.discarded + s.queued }
}

action step = any {
  { nondet c = Callers.oneOf(); any { request(c), checked(c) } },
  { nondet c = StopCallers.oneOf(); stopReturns(c) },
  settleStart, drain, stop, joinStop, dispose, s' = s
}

val StartupOwned = all {
  s.cached == (s.start != "idle"), s.task == (s.start == "ready")
}

temporal Fairness = all {
  settleStart.weakFair(s), drain.weakFair(s), dispose.weakFair(s),
  Callers.forall(c => checked(c).weakFair(s)),
  StopCallers.forall(c => stopReturns(c).weakFair(s))
}

temporal RetryWithoutFairness = (s.retried and s.queued > 0)
  .leadsTo(s.queued == 0 or s.phase == "stopped")
// Fair storage and scheduler actions cannot manufacture a later request.

action legacyFailedStart = all {
  s.start == "pending", s' = { ...s, start: "idle", failures: 1 }
}

action legacyJoinReturnsEarly = all {
  s.phase == "stopping", s.stopCalls.get(1) == "idle",
  s' = { ...s, stopCalls: s.stopCalls.set(1, "returned") }
}

action readOrdinary = all {
  s.phase == 0, s' = { ...s, phase: 1, collected: Set(1) }
}

action readSources = all {
  s.phase == 1, s' = { ...s, phase: 2, collected: s.collected.union(Set(2, 3)) }
}

action collectMedia = all {
  s.phase == 2, s' = { ...s, phase: 3, media: s.collected.contains(2) }
}

action wipe = all {
  s.phase == 3, s' = { ...s, phase: 4, stored: s.stored.exclude(s.collected) }
}

action legacySkipSources = all {
  s.phase == 1, s' = { ...s, phase: 3, media: s.collected.contains(2) }
}

action init = s' = {
  rows: Set(), sequence: 0, epoch: 0, blocked: 0,
  cursor: emptyCursor, prior: emptyCursor,
  page: { query: emptyCursor, status: "none", returned: Set(), complete: false }
}

action appendNotice = all {
  s.sequence < 3,
  s' = { ...s, rows: s.rows.union(Set(s.sequence + 1)), sequence: s.sequence + 1 },
}

action remove(id: int): bool = all {
  s.rows.contains(id),
  s' = { ...s, rows: s.rows.exclude(Set(id)), blocked: if (s.blocked == id) 0 else s.blocked },
}

action block(id: int): bool = all {
  id == 0 or s.rows.contains(id),
  s' = { ...s, blocked: id },
}

action replaceInbox = all {
  s.epoch == 0,
  s' = { ...s, rows: Set(), sequence: 0, epoch: 1, blocked: 0, prior: s.cursor },
}

action begin = all {
  s.cursor.epoch != s.epoch or s.cursor.after == s.cursor.through,
  read({ epoch: s.epoch, after: 0, through: s.sequence }),
}

action invalidCurrent = read({
  epoch: s.epoch, after: s.sequence + 1, through: s.sequence + 1
})

action step = {
  nondet id = 0.to(3).oneOf()
  any {
    appendNotice, remove(id), block(id), replaceInbox, begin, nextPage,
    replayOld, invalidCurrent, s' = s
  }
}

temporal FailedPagesKeepCursor = always((
  errors.contains(next(s.page.status)).implies(next(s.cursor) == s.cursor)
).orKeep(s))

action init = s' = { memory: Set(), disk: Set(), readMarks: Set(), diskReadMarks: Set(), sequence: 0, diskSequence: 0,
  phase: "idle", uncertain: false, closing: false, stopped: false, operation: "none",
  target: 1, published: Set(), everCommitted: Set(), readRows: Set(), observedReadMarks: Set(), readSequence: 0, readValid: false, result: "none" }

action admit(operation: str, target: int): bool = all {
  s.phase == "idle" and not(s.closing),
  s' = { ...s, operation: operation, target: target,
    phase: if (s.uncertain) "recovering" else "mutating", readValid: false, result: "pending" },
}

action mutate = all {
  s.phase == "mutating",
  s.operation != "append" or s.sequence < 2,
  val sequence = if (s.operation == "append") s.sequence + 1 else s.sequence
  val memory = if (s.operation == "append") s.memory.union(Set(sequence))
    else if (s.operation == "delete") s.memory.exclude(Set(s.target))
    else if (s.operation == "mark-read") s.memory else Set()
  val readMarks = if (s.operation == "clear") Set()
    else if (s.operation == "delete") s.readMarks.exclude(Set(s.target))
    else if (s.operation == "mark-read" and memory.contains(s.target)) s.readMarks.union(Set(s.target))
    else s.readMarks
  s' = { ...s, sequence: sequence, memory: memory, readMarks: readMarks, phase: "persisting" },
}

action exhausted = all {
  s.phase == "mutating" and s.operation == "append" and s.sequence == 2,
  s' = { ...s, phase: "idle", result: "failed" },
}

action reconcile(readable: bool): bool = all {
  Set("reconciling", "recovering").contains(s.phase),
  s' = { ...s, memory: if (readable) s.disk else s.memory,
    sequence: if (readable) s.diskSequence else s.sequence,
    readMarks: if (readable) s.diskReadMarks else s.readMarks, uncertain: not(readable),
    phase: if (readable and s.phase == "recovering") "mutating" else "idle",
    result: if (readable and s.phase == "recovering") "pending" else "failed" },
}
// Observational fan-out may succeed or fail. Both outcomes leave durable data.

action broadcast(delivered: bool): bool = all {
  s.phase == "broadcasting",
  s' = { ...s, published: if (delivered and s.operation == "append")
    s.published.union(Set(s.sequence)) else s.published, phase: "idle", result: "ok" },
}

action read = all {
  s.phase == "idle" and not(s.closing) and not(s.uncertain),
  s' = { ...s, readRows: s.memory, observedReadMarks: s.readMarks, readSequence: s.sequence, readValid: true },
}

action drained = all {
  s.closing and s.phase == "idle" and not(s.stopped),
  s' = { ...s, stopped: true, memory: Set(), readMarks: Set(), readValid: false },
}

action restart = all {
  s.stopped,
  s' = { ...s, memory: s.disk, readMarks: s.diskReadMarks, sequence: s.diskSequence, uncertain: false,
    closing: false, stopped: false, readValid: false },
}

action step = {
  nondet target = ids.oneOf()
  nondet operation = Set("append", "delete", "clear", "mark-read").oneOf()
  nondet outcome = Set("ack", "reject-before", "reject-after").oneOf()
  nondet flag = Set(true, false).oneOf()
  any { admit(operation, target), mutate, exhausted, persist(outcome), reconcile(flag),
    broadcast(flag), read, stop, drained, restart, s' = s }
}

action submit = all {
  s.admitted == Missing,
  s' = { ...s, admitted: Present(s.producer) },
}

action materialize = all {
  s.admitted != Missing and s.memory == Missing and s.disk == Missing,
  s' = { ...s, memory: s.admitted },
}

action persist = all {
  s.memory != Missing,
  s' = { ...s, disk: s.memory },
}
// A normal read may see provisional memory. Durable reads and events use
// the same detached payload after commit.

action expose = all {
  s.memory != Missing,
  s' = { ...s, observer: s.memory },
}

action observerChanges(value: str): bool = all {
  s.observer != Missing,
  s' = { ...s, observer: Present(value) },
}

action stop = all {
  s.disk != Missing and s.memory != Missing,
  s' = { ...s, memory: Missing },
}

action restart = all {
  s.disk != Missing and s.memory == Missing,
  s' = { ...s, memory: s.disk },
}

action step = {
  nondet value = Set("original", "edited").oneOf()
  any { submit, producerChanges(value), materialize, persist, expose, observerChanges(value), stop, restart, s' = s }
}

pure def active(stored: Slot, now: int): bool = match stored {
  | Empty => false
  | Row(n) => match n.expiry {
    | Deadline(end) => now < end
    | _ => true
  }
}

pure def countAfter(stored: Slot, now: int): Count =
  if (not(active(stored, now))) Implicit
  else match stored {
    | Empty => Implicit
    | Row(n) => match n.count {
      | Implicit => Explicit(2)
      | Explicit(previous) => Explicit(previous + 1)
    }
  }

pure def expiration(request: Request, now: int): Expiry =
  if (request.silent and request.expiry == Unspecified) Deadline(now + 1)
  else request.expiry

pure def exactApproval(stored: Slot): bool = match stored {
  | Empty => false
  | Row(n) => n.title == approval.title and not(n.read) and not(n.silent)
    and Set(Unspecified, Permanent).contains(n.expiry) and n.count == Implicit
}

action request(intent: Intent): bool = all {
  s.pending == Idle and intent != Idle and s.sequence < 3,
  s' = { ...s, pending: intent },
}

action settle = all {
  s.pending != Idle,
  val stored = match s.pending {
    | Idle => s.stored
    | Coalesce(input) => {
      val count = if (input.count == Implicit) countAfter(s.stored, s.now) else input.count
      createRow(s.sequence, s.now, input, count)
    }
    | EnsureApproval => if (exactApproval(s.stored)) s.stored
      else createRow(s.sequence, s.now, approval, Implicit)
  }
  s' = { ...s, sequence: if (stored == s.stored) s.sequence else s.sequence + 1,
    pending: Idle, stored: stored },
}

action markRead = all {
  s.pending == Idle,
  val stored = match s.stored {
    | Empty => Empty
    | Row(n) => Row({ ...n, read: true })
  }
  all {
    stored != s.stored,
    s' = { ...s, stored: stored },
  }
}

action step = {
  nondet input = requests.oneOf()
  any { request(Coalesce(input)), request(EnsureApproval), settle, tick, markRead, s' = s }
}

val SequenceTracksRetainedRow = match s.stored {
  | Empty => s.sequence == 0
  | Row(n) => n.id == s.sequence and 1 <= s.sequence and s.sequence <= 3
}

val incrementedCount = match retainedCount {
  | Implicit => Explicit(2)
  | Explicit(count) => Explicit(count + 1)
}

val input = match s.admission {
  | Open => { category: "general", priority: "default", expiry: Unspecified }
  | Accepted(request) => request
  | Committed(request) => request
}

val notice = match s.row {
  | Empty => { priority: "normal", expiry: Unspecified, created: 0, read: false }
  | Stored(value) => value
}

val visible = s.row != Empty and (match notice.expiry {
  | Deadline(end) => s.now < end
  | _ => true
})

action admit(request: Request): bool = all {
  s.admission == Open,
  s' = { ...s, admission: Accepted(request) },
}

action persist = all {
  s.row == Empty and s.admission != Open,
  s' = { ...s, admission: Committed(input),
    row: Stored({ priority: chosenPriority(input), expiry: chosenExpiry(input, s.now), created: s.now, read: false }) },
}

action markRead = all {
  s.row != Empty and not(notice.read),
  s' = { ...s, row: Stored({ ...notice, read: true }) },
}

action step = {
  nondet category = categories.oneOf()
  nondet priority = priorities.union(Set("default")).oneOf()
  nondet expiry = Set(Unspecified, Permanent, Deadline(1)).oneOf()
  nondet now = 0.to(2).oneOf()
  any { admit({ category: category, priority: priority, expiry: expiry }),
    persist, markRead, clockChanges(now), s' = s }
}

pure val valid: Snapshot = { headerOK: true, epoch: "old", watermark: 3,
  rows: ["a", "b"], coordinates: Map("a" -> 1, "b" -> 3), unsafe: Set() }
// Representative semantic failures, selected one at a time.

pure def completeCoordinates(snapshot: Snapshot): bool = and {
  snapshot.headerOK, snapshot.watermark >= 0,
  snapshot.coordinates.keys().size() == snapshot.rows.length(),
  snapshot.rows.indices().forall(i => {
    val row = snapshot.rows.nth(i)
    if (not(snapshot.coordinates.keys().contains(row)) or snapshot.unsafe.contains(row)) false
    else snapshot.coordinates.get(row) > 0 and snapshot.coordinates.get(row) <= snapshot.watermark
      and (if (i == 0) true
        else if (not(snapshot.coordinates.keys().contains(snapshot.rows.nth(i - 1)))) false
        else snapshot.coordinates.get(row) > snapshot.coordinates.get(snapshot.rows.nth(i - 1)))
  }),
}

action read(succeeded: bool): bool = {
  val stored = s.store.snapshot
  val uniqueLegacy = stored.rows.indices().map(i => stored.rows.nth(i)).size() == stored.rows.length()
  all {
    s.phase == "read",
    s' = if (not(succeeded)) { ...s, phase: "failed" }
      else if (s.store.format == "missing")
        { ...s, candidate: empty, phase: "persist" }
      else if (s.store.format == "legacy")
        if (uniqueLegacy) { ...s, candidate: migrate(stored.rows), phase: "persist" }
        else { ...s, phase: "failed" }
      else if (not(stored.headerOK) or stored.watermark < 0
        or stored.coordinates.keys().size() != stored.rows.length())
        { ...s, phase: "failed" }
      else { ...s, candidate: stored, phase: "validate", index: 0, previous: 0 },
  }
}

action validate = all {
  s.phase == "validate",
  s' = if (s.index == s.candidate.rows.length()) { ...s, phase: "ready" }
    else {
      val row = s.candidate.rows.nth(s.index)
      if (not(s.candidate.coordinates.keys().contains(row)) or s.candidate.unsafe.contains(row))
        { ...s, phase: "failed" }
      else {
        val coordinate = s.candidate.coordinates.get(row)
        if (coordinate <= s.previous or coordinate > s.candidate.watermark) { ...s, phase: "failed" }
        else { ...s, index: s.index + 1, previous: coordinate }
      }
    },
}

action persist(outcome: str): bool = all {
  s.phase == "persist",
  s' = { ...s, store: if (outcome == "before-failure") s.store
    else { format: "v2", snapshot: s.candidate },
    phase: if (outcome == "ack") "ready" else "failed" },
}

action retry = all {
  s.phase == "failed",
  s' = { ...s, phase: "read", candidate: empty, index: 0, previous: 0 },
}

action repair = all {
  s.phase == "failed", s' = { ...s, store: { format: "v2", snapshot: valid } },
}

action step = {
  nondet success = Set(true, false).oneOf()
  nondet outcome = Set("ack", "before-failure", "after-failure").oneOf()
  any { read(success), validate, persist(outcome), retry, repair, s' = s }
}

action init = s' = {
  availability: "failed", phase: "idle", failures: 0, remaining: 0,
  receipt: { outcome: "none", busy: false, cooling: false, availability: "failed" }
}

action request = {
  // A successful load releases the recovery map before its finally runs.
  val busy = Set("loading", "failure-finally").contains(s.phase)
  val eligible = not(busy) and s.availability == "failed" and s.remaining == 0
  val registered = not(busy) and s.availability == "registered"
  s' = { ...s,
    receipt: { busy: busy, cooling: s.remaining > 0, availability: s.availability,
      outcome: if (busy) "in-flight"
        else if (s.availability != "failed") "unavailable"
        else if (s.remaining > 0) "backoff" else "started" },
    phase: if (eligible) "loading" else s.phase,
    availability: if (eligible) "registering" else s.availability,
    failures: if (registered) 0 else s.failures,
    remaining: if (registered) 0 else s.remaining }
}

action loaded = all {
  s.phase == "loading",
  s' = { ...s, phase: "success-finally", availability: "registered",
    failures: 0, remaining: 0 },
}

action failed = all {
  s.phase == "loading",
  val failures = if (s.failures == 6) 6 else s.failures + 1
  s' = { ...s, phase: "failure-finally", availability: "failed",
    failures: failures, remaining: delay(failures) },
}

action finalize = all {
  Set("success-finally", "failure-finally").contains(s.phase),
  s' = { ...s, phase: "idle" },
}

action tick = all {
  s.remaining > 0,
  s' = { ...s, remaining: s.remaining - 1 },
}

action cooldownElapsed = all {
  s.remaining > 0,
  s' = { ...s, remaining: 0 },
}

action externalAvailability(availability: str): bool = all {
  s.phase == "idle",
  s' = { ...s, availability: availability },
}
// A wall-clock jump or an idle observer has no effect on elapsed time.

action step = {
  nondet availability = availabilities.oneOf()
  any {
    request, loaded, failed, finalize, tick, cooldownElapsed,
    externalAvailability(availability), wallClockAdjusted
  }
}

val BoundedCooldown = all {
  s.failures >= 0 and s.failures <= 6,
  s.remaining >= 0 and s.remaining <= delay(s.failures),
}

val PhaseMatchesAvailability = all {
  (s.phase == "loading").implies(s.availability == "registering"),
  (s.phase == "success-finally").implies(s.availability == "registered"),
  (s.phase == "failure-finally").implies(s.availability == "failed"),
}

temporal OnlyIdleEntersLoad = always((
  (s.phase != "loading" and next(s.phase) == "loading").implies(s.phase == "idle")
).orKeep(s))

action init = s' = { availability: "failed", mapped: 0, allocated: 0,
  records: Owners.mapBy(_ => { phase: "idle", cooling: false }),
  receipt: { outcome: "none", busy: false, cooling: false, availability: "failed" } }

action request = {
  val eligible = not(mappedBusy) and s.availability == "failed" and not(mappedCooling)
  val owner = if (s.mapped != 0) s.mapped else if (s.allocated == 0) 1 else 2
  all {
    not(eligible) or s.mapped != 0 or s.allocated < 2,
    s' = { ...s, receipt: { busy: mappedBusy, cooling: mappedCooling, availability: s.availability,
        outcome: if (mappedBusy) "in-flight" else if (s.availability != "failed") "unavailable"
          else if (mappedCooling) "backoff" else "started" },
      mapped: if (eligible) owner else if (not(mappedBusy) and s.availability == "registered") 0 else s.mapped,
      allocated: if (eligible and s.mapped == 0) s.allocated + 1 else s.allocated,
      records: if (eligible) s.records.set(owner, { phase: "loading", cooling: false }) else s.records,
      availability: if (eligible) "registering" else s.availability },
  }
}

action observeRegistered = all {
  s.availability == "registered", s' = { ...s, mapped: 0 },
}

action returnLoad(owner: int): bool = all {
  s.records.get(owner).phase == "loading", s.availability == "registered",
  s' = { ...s, records: s.records.set(owner, { ...s.records.get(owner), phase: "returned" }) },
}

action succeed(owner: int): bool = all {
  s.records.get(owner).phase == "returned",
  s' = { ...s, mapped: if (s.mapped == owner) 0 else s.mapped,
    records: s.records.set(owner, { ...s.records.get(owner), phase: "success-finally" }) },
}

action loadFailed(owner: int): bool = all {
  s.records.get(owner).phase == "loading",
  s' = { ...s, records: s.records.set(owner, { phase: "failure-finally", cooling: true }) },
}

action finalize(owner: int): bool = all {
  Set("success-finally", "failure-finally").contains(s.records.get(owner).phase),
  s' = { ...s, records: s.records.set(owner, { ...s.records.get(owner), phase: "idle" }) },
}

action cooldownElapsed(owner: int): bool = all {
  s.records.get(owner).cooling,
  s' = { ...s, records: s.records.set(owner, { ...s.records.get(owner), cooling: false }) },
}
// The logger, runtime error boundary and event bus catch their observers.

action complete(owner: int): bool = any {
  returnLoad(owner), succeed(owner), loadFailed(owner), finalize(owner),
}

action step = {
  nondet owner = Owners.oneOf()
  nondet availability = availabilities.oneOf()
  any { request, externalAvailability(availability), observeRegistered, complete(owner),
    cooldownElapsed(owner), diagnosticObserverThrows }
}

action enter(sender: int): bool = all {
  s.phase == "idle",
  s' = { ...s, active: sender, phase: "reading", result: "pending", created: false },
}

action read = all {
  s.phase == "reading",
  val count = senders.filter(sender => s.rows.get(sender) == "live").size()
  s' = { ...s, observedCount: count,
    phase: if (s.rows.get(s.active) == "live") "updating"
      else if (count >= 2) "rejecting" else "creating" },
}

action write(ok: bool): bool = all {
  Set("updating", "creating").contains(s.phase),
  s' = { ...s, rows: if (ok and s.phase == "creating") s.rows.set(s.active, "live") else s.rows,
    lastSender: s.active, active: none, phase: "idle", result: if (ok) "ok" else "failed",
    created: ok and s.phase == "creating" },
}

action reject = all {
  s.phase == "rejecting",
  s' = { ...s, lastSender: s.active, active: none, phase: "idle", result: "full", created: false },
}

action expire(sender: int): bool = all {
  s.rows.get(sender) == "live",
  s' = { ...s, rows: s.rows.set(sender, "expired") },
}

action clean(sender: int): bool = all {
  s.rows.get(sender) == "expired",
  s' = { ...s, rows: s.rows.set(sender, "absent") },
}

action step = {
  nondet sender = senders.oneOf()
  any { enter(sender), read, write(true), write(false), reject, expire(sender), clean(sender), s' = s }
}

val AdmissionUsesBoundedRead = (s.phase == "creating").implies(s.observedCount < 2)
// The model separates expiry after read from update. Updating a previously
// eligible row does not renew createdAt and therefore does not revive it.

action begin = all {
  s.phase == "idle" and s.request,
  s' = { ...s, phase: "grant", result: "pending" },
}

action grant(ok: bool): bool = all {
  s.phase == "grant",
  s' = { ...s, grant: s.grant or ok, phase: if (ok) "consume" else "idle",
    result: if (ok) "pending" else "failed" },
}

action consume(ok: bool): bool = all {
  s.phase == "consume",
  s' = { ...s, request: s.request and not(ok), phase: "idle", result: if (ok) "ok" else "failed",
    consumedWithoutGrant: s.consumedWithoutGrant or (ok and not(s.grant)) },
}

action claim(sender: int): bool = {
  val held = s.retained.indices().exists(i => s.retained.nth(i) == sender) and s.live.contains(sender)
  val fresh = if (s.retained.length() >= 2)
    s.retained.select(owner => s.live.contains(owner)) else s.retained
  val bounded = if (fresh.length() >= 2) fresh.tail() else fresh
  val updated = if (bounded.indices().exists(i => bounded.nth(i) == sender)) bounded else bounded.append(sender)
  s' = if (held) { ...s, lastSender: sender, accepted: false, wasRetained: true }
    else { retained: updated, live: s.live.union(Set(sender)), lastSender: sender,
      accepted: true, wasRetained: false }
}

pure val owners = Set(0, 1, 2, 3, 4)
// 0/1 differ at a hyphen-delimited channel/sender boundary. 0/2 differ only
// in agent. 3/4 differ at a colon-delimited reply-claim boundary.

action claim(owner: int, legacy: bool): bool = {
  val key = if (legacy) legacyReplyKey(owner) else owner
  s' = {
    ownersSeen: s.ownersSeen.union(Set(owner)),
    claimKeys: s.claimKeys.union(Set(key)),
    accepted: not(s.claimKeys.contains(key)),
    first: not(s.ownersSeen.contains(owner)),
  }
}

action admit(owner: int, legacy: bool): bool = {
  val key = if (legacy) legacyRequestKey(owner) else owner
  val accepted = s.rows.get(key) == -1 or s.rows.get(key) == owner
  s' = { rows: if (accepted) s.rows.set(key, owner) else s.rows, accepted: accepted }
}

action write(owner: int, key: int): bool = {
  val stored = s.ownerKey.get(owner)
  val insert = stored == -1 and s.rows.get(key) == -1
  val accepted = stored >= 0 or insert
  s' = {
    rows: if (insert) s.rows.set(key, owner) else s.rows,
    ownerKey: if (insert) s.ownerKey.set(owner, key) else s.ownerKey,
    lastOwner: owner, lastKey: if (stored >= 0) stored else key,
    accepted: accepted, reported: true,
  }
}
// Models the former unconditional ID return after ON CONFLICT DO NOTHING.

action legacyWrite(owner: int, key: int): bool = {
  val insert = s.ownerKey.get(owner) == -1 and s.rows.get(key) == -1
  s' = {
    rows: if (insert) s.rows.set(key, owner) else s.rows,
    ownerKey: if (insert) s.ownerKey.set(owner, key) else s.ownerKey,
    lastOwner: owner, lastKey: key, accepted: true, reported: true,
  }
}

action remove(key: int): bool = {
  val owner = s.rows.get(key)
  s' = { ...s, rows: s.rows.set(key, -1),
    ownerKey: if (owner >= 0) s.ownerKey.set(owner, -1) else s.ownerKey,
    reported: false }
}

action step = {
  nondet owner = owners.oneOf()
  nondet key = rowKeys.oneOf()
  any { write(owner, key), remove(key) }
}

action init = s' = {
  marker: false,
  requests: Requests.mapBy(_ => {
    phase: "idle", attempts: 0, committedAt: 0, notice: "none"
  })
}

action submit(id: int): bool = all {
  entry(id).phase == "idle",
  update(id, { ...entry(id), phase: if (s.marker) "deduplicated" else "queued" })
}

action beginAttempt(id: int): bool = all {
  entry(id).phase == "queued", entry(id).attempts < MaxAttempts,
  update(id, { ...entry(id), attempts: entry(id).attempts + 1,
    phase: if (s.marker) "deduplicated" else "scrubbing"
  })
}

action settleScrub(id: int, ok: bool): bool = all {
  entry(id).phase == "scrubbing",
  if (ok) update(id, { ...entry(id), phase: "marking" }) else failAttempt(id)
}

action settleMarker(id: int, confirmed: bool): bool = all {
  entry(id).phase == "marking",
  if (confirmed) s' = { marker: true,
    requests: s.requests.set(id, { ...entry(id),
      phase: "notifying", committedAt: entry(id).attempts
    })
  } else failAttempt(id)
}

action settleNotice(id: int, ok: bool): bool = all {
  entry(id).phase == "notifying",
  update(id, { ...entry(id), phase: "done", notice: if (ok) "sent" else "rejected" })
}

action settleFailureNotice(id: int): bool = all {
  entry(id).phase == "failing",
  update(id, { ...entry(id), phase: "exhausted" })
}

action advance(id: int): bool = any {
  beginAttempt(id), settleFailureNotice(id),
  { nondet ok = Bool.oneOf(); any {
    settleScrub(id, ok), settleMarker(id, ok), settleNotice(id, ok)
  } }
}

action step = any {
  { nondet id = Requests.oneOf(); any { submit(id), advance(id) } },
  s' = s
}

val ConfirmedAttemptCannotRetry = Requests.forall(id =>
  (entry(id).committedAt > 0) implies all {
    entry(id).attempts == entry(id).committedAt,
    entry(id).phase.in(Set("notifying", "done"))
  })

pure def roomPending(v: State, r: int): Set[int] = v.roomIndex.get(r)
// Both concrete indexes are removed in one synchronous finally callback.
// A settled callback's cooperation selector cannot affect any future action.

pure def settleTask(v: State, t: int): State = {
  ...v,
  task: v.task.set(t, "settled"),
  runtimeIndex: v.runtimeIndex.exclude(Set(t)),
  roomIndex: if (v.room.get(t) == 0) v.roomIndex
    else v.roomIndex.set(v.room.get(t), v.roomIndex.get(v.room.get(t)).exclude(Set(t))),
  cooperative: v.cooperative.exclude(Set(t))
}

action Admit(t: int, r: int, mode: str, cooperative: bool): bool = all {
  s.task.get(t) == "new",
  not(s.quarantined),
  (mode == "explicit" and Rooms.contains(r)) or
  (mode == "ambient" and not(ExplicitOwnership) and Rooms.contains(r)) or
  (mode == "unscoped" and not(ExplicitOwnership) and r == 0) or
  (mode == "diagnostic" and r == 0),
  s' = {
    ...s,
    task: s.task.set(t, "queued"),
    room: s.room.set(t, r),
    // Admission mode is an argument, not retained tracker state. Sticky
    // witnesses retain the guard obligations without distinct alias states.
    scopedAdmissionValid: s.scopedAdmissionValid and
      (r == 0 or Set("explicit", "ambient").contains(mode)),
    explicitAdmissionValid: s.explicitAdmissionValid and
      (not(ExplicitOwnership) or not(Set("ambient", "unscoped").contains(mode))),
    runtimeIndex: s.runtimeIndex.union(Set(t)),
    roomIndex: if (r == 0) s.roomIndex else s.roomIndex.set(r, s.roomIndex.get(r).union(Set(t))),
    cooperative: if (cooperative) s.cooperative.union(Set(t)) else s.cooperative
  }
}
// Rejected calls leave all task and boundary ownership state intact.

action Refuse = {
  nondet reason = Set("partial-pair", "stale-lease", "wrong-room", "duplicate-boundary", "quarantined", "explicit-required").oneOf()
  all {
    (reason == "quarantined" implies s.quarantined),
    (Set("partial-pair", "stale-lease", "wrong-room", "explicit-required").contains(reason) implies not(s.quarantined)),
    (reason == "explicit-required" implies ExplicitOwnership),
    (reason == "duplicate-boundary" implies Rooms.exists(r => Set("pending", "delivered", "failed").contains(s.boundary.get(r)))),
    s' = s
  }
}

action BeginDelivery(r: int): bool = all {
  s.boundary.get(r) == "none", s.roomDrain.get(r) == "idle",
  s' = {
    ...s,
    boundary: s.boundary.set(r, "pending")
  }
}

action ResolveDelivery(r: int, delivered: bool): bool = all {
  s.boundary.get(r) == "pending",
  s' = {
    ...s,
    boundary: s.boundary.set(r, if (delivered) "delivered" else "failed"),
    roomDrain: s.roomDrain.set(r, if (s.quarantined) "rejected" else if (roomPending(s, r).size() == 0) "returned" else "waiting"),
    roomBatch: s.roomBatch.set(r, roomPending(s, r)),
    permission: Tasks.mapBy(t =>
      if (s.task.get(t) == "waiting" and s.room.get(t) == r)
        (if (delivered) "yes" else "no")
      else s.permission.get(t))
  }
}
// The queued microtask checks cancellation before invoking the callback.
// A real callback may wait for the boundary and then honor its boolean.

action AdvanceTask(t: int): bool = any {
  all {
    s.task.get(t) == "queued",
    s.aborted.contains(t),
    s' = settleTask(s, t)
  },
  all {
    s.task.get(t) == "queued",
    not(s.aborted.contains(t)),
    s' = {
      ...s,
      invoked: s.invoked.union(Set(t)),
      task: s.task.set(t,
        if (s.room.get(t) != 0 and s.boundary.get(s.room.get(t)) == "pending")
          "waiting"
        else "running"),
      permission: s.permission.set(t,
        if (s.room.get(t) != 0 and s.boundary.get(s.room.get(t)) == "failed")
          "no"
        else if (s.room.get(t) != 0 and s.boundary.get(s.room.get(t)) == "pending")
          "unknown"
        else "yes")
    }
  },
  all {
    s.task.get(t) == "waiting",
    s.permission.get(t) != "unknown",
    s' = {
      ...s,
      task: s.task.set(t, "running")
    }
  },
  all {
    s.task.get(t) == "running",
    s' = settleTask(s, t)
  }
}
// Effects can occur before completion or failure. Cancellation only prevents
// them for callbacks which cooperate with their AbortSignal.

action TaskEffect(t: int): bool = all {
  s.task.get(t) == "running", s.permission.get(t) == "yes",
  not(s.cooperative.contains(t) and s.aborted.contains(t)),
  s' = {
    ...s,
    effects: s.effects.union(Set(t))
  }
}
// Rejected callbacks are reported and removed from both indexes. The error
// history belongs to the diagnostic sink, not retained task-tracker state.

action RejectTask(t: int): bool = all {
  Set("running", "waiting").contains(s.task.get(t)),
  s' = settleTask(s, t)
}

action BeginRoomDrain(r: int): bool = all {
  s.roomDrain.get(r) == "idle", s.boundary.get(r) == "none",
  s' = {
    ...s,
    roomDrain: s.roomDrain.set(r, if (s.quarantined) "rejected" else if (roomPending(s, r).size() == 0) "returned" else "waiting"),
    roomBatch: s.roomBatch.set(r, roomPending(s, r))
  }
}

action AdvanceRoomDrain(r: int): bool = all {
  s.roomDrain.get(r) == "waiting", s.roomBatch.get(r).intersect(pending(s)).size() == 0,
  s' = {
    ...s,
    roomDrain: s.roomDrain.set(r, if (roomPending(s, r).size() == 0) "returned" else "waiting"),
    roomBatch: s.roomBatch.set(r, roomPending(s, r))
  }
}

action CloseDelivery(r: int): bool = all {
  Set("delivered", "failed").contains(s.boundary.get(r)),
  Set("returned", "rejected").contains(s.roomDrain.get(r)),
  s' = {
    ...s,
    boundary: s.boundary.set(r, "closed")
  }
}

action BeginRuntimeDrain(abortable: bool): bool = all {
  s.runtimeDrain == "idle",
  s' = {
    ...s,
    runtimeDrain: if (s.quarantined) "rejected" else if (pending(s).size() == 0) "returned" else "waiting",
    runtimeBatch: pending(s),
    abortableDrain: abortable
  }
}

action AdvanceRuntimeDrain = all {
  s.runtimeDrain == "waiting", s.runtimeBatch.intersect(pending(s)).size() == 0,
  s' = {
    ...s,
    runtimeDrain: if (pending(s).size() == 0) "returned" else "waiting",
    runtimeBatch: pending(s)
  }
}
// External quarantine aborts callbacks but does not retroactively reject a
// drain which already passed its entry check. Its own signal must abort.

action Quarantine = all {
  not(s.quarantined),
  s' = {
    ...s,
    quarantined: true,
    aborted: s.aborted.union(pending(s))
  }
}

action AbortRuntimeDrain = all {
  s.runtimeDrain == "waiting", s.abortableDrain,
  s' = {
    ...s,
    quarantined: true,
    aborted: s.aborted.union(pending(s)),
    runtimeDrain: "rejected"
  }
}

val TaskIndexesAgree = and {
  s.runtimeIndex == Tasks.filter(t => Set("queued", "waiting", "running").contains(s.task.get(t))),
  Rooms.forall(r => s.roomIndex.get(r) == s.runtimeIndex.filter(t => s.room.get(t) == r))
}

temporal DrainsFinishExpanded = Fairness implies and {
  always(s.runtimeDrain == "waiting" implies eventually(s.runtimeDrain != "waiting")),
  Rooms.forall(r => always(s.roomDrain.get(r) == "waiting" implies eventually(s.roomDrain.get(r) != "waiting"))),
  Rooms.forall(r => always(s.boundary.get(r) == "pending" implies eventually(s.boundary.get(r) == "closed")))
}

// Each of the two room observers/boundaries and the runtime observer can
// start once. Under these finite, monotone observer states, every started
// observer eventually finishing is equivalent to eventual permanent
// quiescence. The compact form uses one TLC liveness graph rather than five.
// DrainsFinishExpanded above retains the per-observer statement explicitly.

val ObserversQuiescent = and {
  s.runtimeDrain != "waiting",
  Rooms.forall(r => s.roomDrain.get(r) != "waiting"),
  Rooms.forall(r => Set("none", "closed").contains(s.boundary.get(r)))
}

action admit(c: str): bool = all {
  s.pc.get(c) == "idle",
  s' = if (s.closed) { ...s, pc: s.pc.set(c, "rejected") }
    else { ...s, pending: s.pending.union(Set(c)),
      pc: s.pc.set(c, if (c == "daemon") "preflight" else "read") },
}

action readOrPreflightSettles(c: str, succeeded: bool, exclusive: bool): bool = {
  val guarded = not(Repeat) or exclusive
  val accepted = succeeded and not(s.closed) and s.rowExists
    and (not(guarded) or owners.size() == 0)
  all {
    Waiting.contains(s.pc.get(c)),
    s' = { ...s, exclusive: s.exclusive.set(c, guarded),
      pc: s.pc.set(c, if (not(accepted)) "settle"
        else if (Repeat) "worker" else "recheck") },
  }
}

action recheck(c: str, succeeded: bool): bool = all {
  s.pc.get(c) == "recheck",
  s' = { ...s, pc: s.pc.set(c, if (succeeded and s.rowExists and not(s.closed))
    "worker" else "release") },
}

action work(c: str, preserve: bool): bool = all {
  s.pc.get(c) == "worker",
  s' = { ...s, pc: s.pc.set(c, if (preserve) "release" else "write") },
}

action write(c: str): bool = all {
  s.pc.get(c) == "write",
  s' = { ...s, rowExists: Repeat, pc: s.pc.set(c, "release") },
}

action release(c: str): bool = all {
  s.pc.get(c) == "release",
  s' = { ...s, pc: s.pc.set(c, "settle") },
}

action finalize(c: str): bool = all {
  s.pc.get(c) == "settle",
  s' = { ...s, pc: s.pc.set(c, "done"), pending: s.pending.exclude(Set(c)) },
}

action drain = all {
  s.closed, s.pending.size() == 0,
  s' = { ...s, drained: true },
}

action complete(c: str): bool = {
  nondet succeeded = Set(true, false).oneOf()
  nondet exclusive = Set(true, false).oneOf()
  nondet preserve = Set(true, false).oneOf()
  any {
    readOrPreflightSettles(c, succeeded, exclusive), recheck(c, succeeded),
    work(c, preserve), write(c), release(c), finalize(c),
  }
}

action step = {
  nondet c = Calls.oneOf()
  any { admit(c), complete(c), prepareStop, drain, s' = s }
}

action Fire(k: str): bool = {
  val take = s.dirty and s.registry != NoEntry and not(s.busy.contains(s.registry.svc))
  all {
    s.timer, s.adapter != None, s.activeTick == None, s.tk.get(k).pc == "free",
    s' = if (take) {...s, dirty: false,
      tk: s.tk.set(k, {pc: "query", gen: s.gen, id: s.registry.id, svc: s.registry.svc}),
      activeTick: k, taken: s.registry.svc}
    else {...s, dirty: if (s.registry != NoEntry) s.dirty else false}
  }
}

action Query(k: str): bool = {
  val svc = s.tk.get(k).svc
  all {s.tk.get(k).pc == "query", any {
    all {QueryCanFail, s' = marks(settle({...s, dirty: s.dirty or current(s, k)}, k))},
    all {not(current(s, k)), s' = marks(settle(s, k))},
    all {current(s, k), s' = marks(settle(s, k))},
    all {current(s, k), s' = marks({...s,
      stale: s.stale or s.tk.get(k).gen != s.gen or s.registry.id != s.tk.get(k).id,
      tk: s.tk.set(k, {...s.tk.get(k), pc: if (s.stopped.get(svc)) "after" else "run"}),
      inRun: if (s.stopped.get(svc)) s.inRun else s.inRun.set(svc, s.inRun.get(svc) + 1),
      busy: s.busy.union(Set(svc))})}
  }}
}

action RunDone(k: str): bool = {
  val svc = s.tk.get(k).svc
  all {Set("run", "after").contains(s.tk.get(k).pc),
    s' = marks(settle({...s,
      inRun: if (s.tk.get(k).pc == "run") s.inRun.set(svc, s.inRun.get(svc) - 1) else s.inRun,
      busy: s.busy.exclude(Set(svc)), dirty: s.dirty or current(s, k)}, k))
  }
}

action Start(a: str): bool = all {
  s.restarts < MaxRestarts, not(s.timer and s.adapter == a),
  s' = marks({...s, gen: s.gen + 1, adapter: a, activeTick: None,
    dirty: if (s.timer) s.dirty or s.registry != NoEntry else s.dirty,
    timer: true, restarts: s.restarts + 1})
}

action Stop = all {s.restarts < MaxRestarts,
  s' = {...s, gen: s.gen + 1, timer: false, registry: NoEntry, dirty: false,
    adapter: None, activeTick: None, restarts: s.restarts + 1}}

action Register(svc: str): bool = all {
  not(s.stopped.get(svc)), s.adapter != None, s.regs < MaxRegs,
  s' = {...s, nextId: s.nextId + 1, registry: {svc: svc, id: s.nextId + 1},
    dirty: true, regs: s.regs + 1, taken: None}
}

action nextStep = {
  nondet k = Ticks.oneOf()
  nondet a = Adapters.oneOf()
  nondet svc = Services.oneOf()
  any {Fire(k), Query(k), RunDone(k), Start(a), Stop, Register(svc), StopService(svc),
    MarkDirty, all {Finished, s' = s}}
}

action register(owner: str): bool = all {
  s.active, not(s.retired.contains(owner)), s.registration < 2,
  s' = { ...s, registry: owner, registration: s.registration + 1 },
}

action begin(q: str): bool = all {
  s.active, s.registry != "none", s.queries.get(q).phase == "idle",
  s' = { ...s, queries: s.queries.set(q, { phase: "query", owner: s.registry,
    registration: s.registration, generation: s.generation, adapter: s.adapter }) },
}

action unregister(owner: str): bool = s' = { ...s,
  retired: s.retired.union(Set(owner)),
  registry: if (s.registry == owner) "none" else s.registry }

action closeStorage(owner: str): bool = all {
  s.retired.contains(owner), ownedPending(owner).size() == 0,
  s' = { ...s, closed: s.closed.union(Set(owner)) },
}

action closeAdapter(owner: str): bool = all {
  s.retiredAdapters.contains(owner), adapterPending(owner).size() == 0,
  s' = { ...s, closedAdapters: s.closedAdapters.union(Set(owner)) },
}

action settle(q: str, succeeded: bool): bool = all {
  s.queries.get(q).phase == "query",
  s' = { ...s, queries: s.queries.set(q, { ...s.queries.get(q),
    phase: if (succeeded) "result" else "failed" }) },
}

action dispatch(q: str): bool = {
  val query = s.queries.get(q)
  all {
    query.phase == "result", s.active, query.generation == s.generation,
    query.registration == s.registration, query.owner == s.registry,
    s' = { ...s, queries: s.queries.set(q, { ...query, phase: "dispatched" }) },
  }
}

action stopScheduler = all {
  not(s.stopRequested),
  s' = { ...s, active: false, generation: s.generation + 1, registry: "none",
    stopRequested: true, stopQueries: pendingQueries },
}

action returnSchedulerStop = all {
  s.stopRequested, s.stopQueries.intersect(pendingQueries).size() == 0,
  s' = { ...s, stopReturned: true },
}

action restart = all {
  s.stopRequested, not(s.restarted), not(s.retiredAdapters.contains("storage-new")),
  s' = { ...s, active: true, adapter: "storage-new", generation: s.generation + 1, restarted: true },
}

action step = any {
  {
    nondet owner = Services.oneOf()
    any { register(owner), unregister(owner), closeStorage(owner) }
  },
  {
    nondet q = Queries.oneOf()
    any { begin(q), settle(q, true), settle(q, false), dispatch(q) }
  },
  {
    nondet owner = Adapters.oneOf()
    any { retireAdapter(owner), closeAdapter(owner) }
  },
  stopScheduler, returnSchedulerStop, restart, s' = s,
}

action init = s' = {
  phase: "query", includesFirst: true, groupedPeer: false, peerTaskPending: true,
  peerRegistration: 1, capturedPeer: 1, replacementRegistered: false,
  oldPeerUnregistered: false, peerDirty: false, peerDispatches: 0,
  dispatchedRegistration: 0, currentAtDispatch: 0
}

action registerReplacement = all {
  not(s.replacementRegistered),
  s' = { ...s, replacementRegistered: true, peerRegistration: 2, peerDirty: true }
}

action unregisterOldPeer = all {
  not(s.oldPeerUnregistered),
  s' = { ...s, oldPeerUnregistered: true,
    peerRegistration: if (s.peerRegistration == 1) 0 else s.peerRegistration,
    peerDirty: s.peerRegistration != 1 and s.peerDirty }
}

action receiveQuery = all {
  s.phase == "query",
  s' = { ...s, phase: if (s.includesFirst) "first-ready" else "peer-ready",
    groupedPeer: s.peerTaskPending and s.peerRegistration == s.capturedPeer }
}

action dispatchFirst = all {
  s.phase == "first-ready", s' = { ...s, phase: "first-running" }
}

action settleFirst = all {
  s.phase == "first-running", s' = { ...s, phase: "peer-ready" }
}

action skipPeer = all {
  s.phase == "peer-ready", not(peerIsCurrent), s' = { ...s, phase: "done" }
}

action settlePeer = all {
  s.phase == "peer-running", s' = { ...s, phase: "done", peerTaskPending: false }
}

action queryReplacement = all {
  s.phase == "done", s.peerDirty, s.peerTaskPending, s.peerRegistration == 2,
  s' = { ...s, phase: "query", includesFirst: false, groupedPeer: false,
    capturedPeer: s.peerRegistration, peerDirty: false }
}

temporal PeerTaskCompletes = advance.weakFair(s).implies(PeerTaskWithoutFairness)

// Omitting the second identity check lets a previously grouped result cross
// a registration change that occurred during the first service's await.

pure def startWorker(v: State, r: str): State = {...v, pc: v.pc.set(r, "exec"),
  starts: if (v.starts < 2) v.starts + 1 else 2,
  unserved: v.unserved.filter(k => k > v.snap.get(r).rev)}

action Begin(r: str): bool = all {s.pc.get(r) == "idle", any {
  all {Timers.contains(r), s.armed,
    s' = if (s.activeTick != None) {...s, armed: false, deferred: true}
    else {...s, armed: false, activeTick: r, pc: s.pc.set(r, "read")}},
  all {DueRunners.contains(r), s.activeTick == None,
    s' = {...s, activeTick: r, pc: s.pc.set(r, "read")}},
  all {DaemonRunners.union(ByIdRunners).contains(r), s' = {...s, pc: s.pc.set(r, "read")}}
}}

action Read(r: str): bool = {
  val v = {...s, unseen: if (Timers.union(DueRunners).contains(r)) false else s.unseen}
  all {s.pc.get(r) == "read", s' = if (s.row.exists)
    {...v, snap: s.snap.set(r, snapOf(s.row)), pc: s.pc.set(r, "select")}
    else endRun(v, r, false)}
}

action Select(r: str): bool = {
  val snapshot = s.snap.get(r)
  all {s.pc.get(r) == "select", s' =
    if (Scheduled.contains(r) and (snapshot.paused or (Repeat and not(snapshot.due))
      or (Repeat and Blocking and s.inSet))) endRun(s, r, true)
    else if (Guarded and s.inSet) endRun(s, r, true)
    else if (not(Repeat)) {...s, inSet: true, pc: s.pc.set(r, "recheck")}
    else startWorker({...s, inSet: true}, r)
  }
}

action Recheck(r: str): bool = all {s.pc.get(r) == "recheck", any {
  all {s.row.exists, s' = startWorker(s, r)},
  s' = {...s, pc: s.pc.set(r, "release")}
}}

action Work(r: str): bool = {
  val outcomes = Set("preserve").union(if (Repeat)
    Set("ok", "fail").union(if (s.requests < MaxRequests) Set("okWake") else Set())
    else Set("ok"))
  nondet o = outcomes.oneOf()
  all {s.pc.get(r) == "exec", s' = {...s, outcome: s.outcome.set(r, o),
    pc: s.pc.set(r, if (o == "preserve") "release" else "write"),
    starts: if (o == "preserve" and not(Repeat)) s.starts - 1 else s.starts}}
}

action Write(r: str): bool = {
  val snapshot = s.snap.get(r)
  val o = s.outcome.get(r)
  val consume = snapshot.wake or o == "okWake"
  val retained = s.row.wake and s.row.rev != snapshot.rev
  nondet due = Set(false, true).oneOf()
  val v = if (not(Repeat)) {...s, row: {...s.row, exists: false}}
    else if (o == "fail") {...s, row: {...s.row, due: false, failing: true}}
    else if (o == "okWake") {...s,
      row: {...s.row, due: false, failing: false, wake: true,
        wakeDue: (retained and s.row.wakeDue) or due, rev: s.row.rev + 1},
      unserved: s.unserved.union(Set(s.row.rev + 1)), requests: s.requests + 1}
    else {...s, row: {...s.row, due: false, failing: false,
      wake: if (consume) retained else s.row.wake,
      wakeDue: if (consume) retained and s.row.wakeDue else s.row.wakeDue}}
  all {s.pc.get(r) == "write", s' = markDirty({...v, pc: s.pc.set(r, "release")})}
}

action Request = all {Repeat, s.row.exists, s.requests < MaxRequests,
  s' = markDirty({...s, row: {...s.row, wake: true, wakeDue: s.row.wake and s.row.wakeDue,
    rev: s.row.rev + 1}, unserved: s.unserved.union(Set(s.row.rev + 1)), requests: s.requests + 1})}

action nextStep = {
  nondet r = Runners.oneOf()
  any {Begin(r), RunnerStep(r), Elapse, WakeElapse, Request, TogglePause, all {Finished, s' = s}}
}

temporal Fairness = and {
  Runners.forall(r => RunnerStep(r).weakFair(s)),
  Timers.union(DaemonRunners).union(ByIdRunners).forall(r => Begin(r).weakFair(s)),
  DueRunners.forall(r => Begin(r).strongFair(s)),
  Elapse.weakFair(s), WakeElapse.weakFair(s)
}

action Start = all { s.entered, s.phase == "idle",
  s' = {...s, phase: if (aborted) "cancelled" else "active",
    attempts: if (aborted) 0 else 1} }

pure val queued: Writer = {
  stage: "queued", temporary: "absent", renamed: false,
  result: "pending", receipt: "pending",
}

pure def initial(serial: bool): State = {
  file: 0, serial: serial, writers: Writers.mapBy(_ => queued),
}

action serialInit = s' = initial(true)

// Same-process async calls are admitted in invocation order. Distinct
// processes, or a synchronous call beside an async one, have no shared tail.

action admit(writer: int, created: bool): bool = {
  val own = s.writers.get(writer)
  all {
    own.stage == "queued",
    not(s.serial) or writer == 1 or s.writers.get(1).stage == "settled",
    s' = s.with("writers", s.writers.set(writer, {
      ...own, stage: if (created) "writing" else "cleanup",
      temporary: if (created) "partial" else "absent",
      result: if (created) "pending" else "failure",
    })),
  }
}

action finishWrite(writer: int, success: bool): bool = {
  val own = s.writers.get(writer)
  all {
    own.stage == "writing",
    s' = s.with("writers", s.writers.set(writer, {
      ...own, stage: if (success) "renaming" else "cleanup",
      temporary: if (success) "complete" else "partial",
      result: if (success) "pending" else "failure",
    })),
  }
}

action rename(writer: int, success: bool): bool = {
  val own = s.writers.get(writer)
  all {
    own.stage == "renaming", own.temporary == "complete",
    s' = { ...s, file: if (success) writer else s.file,
      writers: s.writers.set(writer, {
        ...own, stage: "cleanup", renamed: success,
        temporary: if (success) "absent" else "complete",
        result: if (success) "success" else "failure",
      }),
    },
  }
}

// A failed rm is diagnostic and cannot replace the publication outcome.

action cleanup(writer: int, removed: bool): bool = {
  val own = s.writers.get(writer)
  all {
    own.stage == "cleanup",
    s' = s.with("writers", s.writers.set(writer, {
      ...own, stage: "settled", receipt: own.result,
      temporary: if (removed) "absent" else own.temporary,
    })),
  }
}

// Process death skips finally. A published rename can outlive an absent
// caller receipt, and a pre-rename temporary file can remain on disk.

action crash(writer: int): bool = {
  val own = s.writers.get(writer)
  all {
    not(s.serial), Set("writing", "renaming", "cleanup").contains(own.stage),
    s' = s.with("writers", s.writers.set(writer,
      { ...own, stage: "crashed", receipt: "unknown" })),
  }
}

action advance(writer: int): bool = {
  nondet success = Set(false, true).oneOf()
  any { admit(writer, success), finishWrite(writer, success),
    rename(writer, success), cleanup(writer, success) }
}

val ReceiptRequiresRename = Writers.forall(writer => {
  val own = s.writers.get(writer)
  (own.receipt == "success" implies own.renamed) and
    (own.receipt == "failure" implies not(own.renamed)) and
    (own.receipt == "unknown" implies own.stage == "crashed")
})
